function getBrisbaneNowParts() {
  const now = new Date();
  const parts = new Intl.DateTimeFormat("en-AU", {
    timeZone: "Australia/Brisbane",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  }).formatToParts(now);

  return Object.fromEntries(parts.map((p) => [p.type, p.value]));
}

function getNowBrisbaneTimestamp() {
  const map = getBrisbaneNowParts();
  return `${map.day}/${map.month}/${map.year} ${map.hour}:${map.minute}:${map.second}`;
}

function getTomorrowBrisbaneDateString() {
  const nowParts = getBrisbaneNowParts();

  const brisbaneTodayUtc = new Date(
    Date.UTC(
      Number(nowParts.year),
      Number(nowParts.month) - 1,
      Number(nowParts.day)
    )
  );

  brisbaneTodayUtc.setUTCDate(brisbaneTodayUtc.getUTCDate() + 1);

  const y = brisbaneTodayUtc.getUTCFullYear();
  const m = String(brisbaneTodayUtc.getUTCMonth() + 1).padStart(2, "0");
  const d = String(brisbaneTodayUtc.getUTCDate()).padStart(2, "0");

  return `${y}-${m}-${d}`;
}

function getFallbackJobStart() {
  return `${getTomorrowBrisbaneDateString()} 08:00:00`;
}

function getFallbackJobEnd() {
  return `${getTomorrowBrisbaneDateString()} 16:00:00`;
}

function mapCsrName(authorName) {
  const value = (authorName || "").toString().trim().toLowerCase();

  if (value === "yela6969" || value === "adminwr") {
    return "jon@windowrevival.com";
  }

  const authorMap = {
    "jhan217458": "jhanefe21@gmail.com",
    "pteesc@gmail.com": "druzkie.",
    "brien.b.bustamante@gmail.com": "brien.b.bv13",
    "jennysdmartinez@gmail.com": "sundaecat.",
    "christinek888": "christinek88@gmail.com",
    "tagabeemie.va@gmail.com": "aimes.exe",
    "rodelpenanueva@gmail.com": "iam_el_rod",
    "jrvsantaagata@gmail.com": "_keimakatsuragi",
  };

  return authorMap[value] || (authorName || "").toString().trim();
}

function normalizeJobDate(dateStr, currentYear, fallbackDateTime) {
  const value = (dateStr || "").toString().trim();

  if (!value) {
    return fallbackDateTime;
  }

  let match;

  match = value.match(/^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})$/);
  if (match) {
    return value;
  }

  match = value.match(/^(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})$/);
  if (match) {
    const [, month, day, hour, minute, second] = match;
    return `${currentYear}-${month}-${day} ${hour}:${minute}:${second}`;
  }

  match = value.match(/^(\d{2})\/(\d{2}) (\d{2}):(\d{2}):(\d{2})$/);
  if (match) {
    const [, day, month, hour, minute, second] = match;
    return `${currentYear}-${month}-${day} ${hour}:${minute}:${second}`;
  }

  match = value.match(/^(\d{2})-(\d{2}) (\d{2}):(\d{2})$/);
  if (match) {
    const [, month, day, hour, minute] = match;
    return `${currentYear}-${month}-${day} ${hour}:${minute}:00`;
  }

  match = value.match(/^(\d{2})\/(\d{2}) (\d{2}):(\d{2})$/);
  if (match) {
    const [, day, month, hour, minute] = match;
    return `${currentYear}-${month}-${day} ${hour}:${minute}:00`;
  }

  match = value.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (match) {
    const [, year, month, day] = match;
    return `${year}-${month}-${day} 00:00:00`;
  }

  match = value.match(/^(\d{2})-(\d{2})$/);
  if (match) {
    const [, month, day] = match;
    return `${currentYear}-${month}-${day} 00:00:00`;
  }

  match = value.match(/^(\d{2})\/(\d{2})$/);
  if (match) {
    const [, day, month] = match;
    return `${currentYear}-${month}-${day} 00:00:00`;
  }

  return fallbackDateTime;
}

function parseDateTimeParts(dateTimeStr) {
  const match = (dateTimeStr || "")
    .toString()
    .trim()
    .match(/^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})$/);

  if (!match) return null;

  return {
    year: Number(match[1]),
    month: Number(match[2]),
    day: Number(match[3]),
    hour: Number(match[4]),
    minute: Number(match[5]),
    second: Number(match[6]),
  };
}

function toDateTimeNumber(parts) {
  if (!parts) return null;

  return Number(
    `${String(parts.year).padStart(4, "0")}${String(parts.month).padStart(2, "0")}${String(parts.day).padStart(2, "0")}${String(parts.hour).padStart(2, "0")}${String(parts.minute).padStart(2, "0")}${String(parts.second).padStart(2, "0")}`
  );
}

function formatDateTimeFromParts(parts) {
  return `${String(parts.year).padStart(4, "0")}-${String(parts.month).padStart(2, "0")}-${String(parts.day).padStart(2, "0")} ${String(parts.hour).padStart(2, "0")}:${String(parts.minute).padStart(2, "0")}:${String(parts.second).padStart(2, "0")}`;
}

function isPastBrisbaneDateTime(dateTimeStr) {
  const bookingParts = parseDateTimeParts(dateTimeStr);
  if (!bookingParts) return false;

  const nowParts = getBrisbaneNowParts();

  const bookingNum = toDateTimeNumber(bookingParts);
  const nowNum = Number(
    `${nowParts.year}${nowParts.month}${nowParts.day}${nowParts.hour}${nowParts.minute}${nowParts.second}`
  );

  return bookingNum < nowNum;
}

function bumpYearIfPast(dateTimeStr, currentYear) {
  if (!isPastBrisbaneDateTime(dateTimeStr)) return dateTimeStr;
  const parts = parseDateTimeParts(dateTimeStr);
  if (!parts) return dateTimeStr;
  const baseYear = Number(currentYear);
  for (let yearOffset = 0; yearOffset <= 1; yearOffset++) {
    const tryYear = baseYear + yearOffset;
    if (tryYear <= parts.year) continue;
    const candidate = formatDateTimeFromParts({ ...parts, year: tryYear });
    if (!isPastBrisbaneDateTime(candidate)) return candidate;
  }
  return dateTimeStr;
}

function ensureNotPastDateTime(dateTimeStr, fallbackDateTime) {
  if (isPastBrisbaneDateTime(dateTimeStr)) {
    return fallbackDateTime;
  }
  return dateTimeStr;
}

function setTimeOnDate(dateTimeStr, hh = "16", mm = "00", ss = "00") {
  const value = (dateTimeStr || "").toString().trim();

  let match = value.match(/^(\d{4}-\d{2}-\d{2}) \d{2}:\d{2}:\d{2}$/);
  if (match) {
    return `${match[1]} ${hh}:${mm}:${ss}`;
  }

  match = value.match(/^(\d{4}-\d{2}-\d{2})$/);
  if (match) {
    return `${match[1]} ${hh}:${mm}:${ss}`;
  }

  return value;
}

return items.map((item) => {
  let parsed = {};

  try {
    let raw = (item.json.output || "{}").toString().trim();
    raw = raw.replace(/^[\x60]{3,}(?:json)?\s*\n?/i, "").replace(/\n?\s*[\x60]{3,}\s*$/i, "").trim();
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) raw = m[0];
    parsed = JSON.parse(raw);
  } catch (err) {
    throw new Error(
      `Failed to parse AI output JSON. output snippet: ${(item.json.output || "").slice(0, 200)}`
    );
  }

  const brisbaneNow = getBrisbaneNowParts();
  const currentYear = brisbaneNow.year;

  const authorName = (parsed.authorName || "").toString().trim();
  const csrName = mapCsrName(authorName);

  const howDidYouHear =
    (parsed.howDidYouHearAboutUs || "").toString().trim() || "Google";

  const manJobNum = Number(parsed.manJob);
  const manJob = Number.isFinite(manJobNum) && manJobNum > 0 ? manJobNum : 1;

  const rawJobStart = (parsed.jobStart || "").toString().trim();
  const rawJobEnd = (parsed.jobEnd || "").toString().trim();

  const fallbackJobStart = getFallbackJobStart();
  const fallbackJobEnd = getFallbackJobEnd();

  let jobStart = normalizeJobDate(rawJobStart, currentYear, fallbackJobStart);

  let jobEnd;
  if (!rawJobEnd) {
    jobEnd = setTimeOnDate(jobStart, "16", "00", "00");
  } else {
    jobEnd = normalizeJobDate(rawJobEnd, currentYear, fallbackJobEnd);
  }

  jobStart = bumpYearIfPast(jobStart, currentYear);
  jobEnd = bumpYearIfPast(jobEnd, currentYear);

  jobStart = ensureNotPastDateTime(jobStart, fallbackJobStart);
  jobEnd = ensureNotPastDateTime(jobEnd, fallbackJobEnd);

  const startNum = toDateTimeNumber(parseDateTimeParts(jobStart));
  const endNum = toDateTimeNumber(parseDateTimeParts(jobEnd));

  if (startNum !== null && endNum !== null && endNum < startNum) {
    jobEnd = setTimeOnDate(jobStart, "16", "00", "00");
  }

  const mobile = (parsed.mobileNumber || "")
    .toString()
    .replace(/\s+/g, "")
    .trim();

  return {
    json: {
      id: (parsed.id || "").toString(),
      channelId: (parsed.channelId || "").toString(),
      authorId: (parsed.authorId || "").toString(),

      authorName,
      csrName,

      timestamp: getNowBrisbaneTimestamp(),

      customerFirstName: (parsed.customerFirstName || "").toString(),
      customerLastName: (parsed.customerLastName || "").toString(),
      customerJobTitle: (parsed.customerJobTitle || "").toString(),

      emailAddress: (parsed.emailAddress || "").toString(),

      streetAddress: (parsed.streetAddress || "").toString(),
      streetAddressDescription: (parsed.streetAddressDescription || "").toString(),

      state: (parsed.state || "").toString(),
      suburb: (parsed.suburb || "").toString(),
      postalCode: (parsed.postalCode || "").toString(),

      mobileNumber: mobile,
      phoneNumber: (parsed.phoneNumber || "").toString(),

      howDidYouHearAboutUs: howDidYouHear,

      isDhWsNsEmporium: parsed.isDhWsNsEmporium ?? false,

      jobServices: (parsed.jobServices || "").toString(),
      jobStart,
      jobEnd,
      jobType: (parsed.jobType || "").toString(),

      jobDescription: (parsed.jobDescription || "").toString(),
      dspNotes: (parsed.dspNotes || "").toString(),

      estTimeHours: Number(parsed.estTimeHours) || 0,
      estPrice: Number(parsed.estPrice) || 0,
      manJob,

      technicianName: (parsed.technicianName || "").toString(),

      recap: (parsed.recap || "").toString(),

      isCreated: true,
    },
  };
});

