const input = $input.all();

function parseJob(item) {
    const content = item.json.content || "";

    const getField = (label) => {
        const escapedLabel = label.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

        const regex = new RegExp(
            `(?:^|\\n)${escapedLabel}:[ \\t]*(.*)`,
            "i"
        );

        const match = content.match(regex);
        return match ? match[1].trim() : "";
    };

    const customerName = getField("Customer Name");
    const nameParts = customerName.split(" ");

    const streetAddress = getField("Street Address");

    let suburb = "";
    let state = "";
    let postalCode = "";

    const addressMatch = streetAddress.match(
        /,\s*([^,]+)\s+([A-Z]{2,3})\s+(\d{4})/
    );

    if (addressMatch) {
        suburb = addressMatch[1].trim();
        state = addressMatch[2].trim();
        postalCode = addressMatch[3].trim();
    }

    const parseDateTime = (value) => {
        const match = value.match(
            /(\d{2})\/(\d{2})\/(\d{4})\s*-\s*(\d+)(am|pm)/i
        );

        if (!match) return "";

        let [, day, month, year, hour, meridian] = match;

        hour = parseInt(hour, 10);

        if (meridian.toLowerCase() === "pm" && hour < 12) hour += 12;
        if (meridian.toLowerCase() === "am" && hour === 12) hour = 0;

        return `${year}-${month}-${day} ${String(hour).padStart(2, "0")}:00:00`;
    };

    // Recap section
    const recapMatch = content.match(
        /\+{10,}\s*\n\s*Recap\s*\n([\s\S]*)$/i
    );

    const recap = recapMatch
        ? recapMatch[1].trim()
        : "";

    // Repairs section
    const repairsMatch = content.match(
        /\n\s*REPAIRS\s*\n([\s\S]*?)\n\s*PRICE ESTIMATE\s*\n/i
    );

    const repairs = repairsMatch
        ? repairsMatch[1].trim()
        : "";

    // Price Estimate section
    const priceEstimateMatch = content.match(
        /\n\s*PRICE ESTIMATE\s*\n([\s\S]*?)(?:\nDSP Notes:|\nEst Time Hours:|\nEst Price:)/i
    );

    const priceEstimate = priceEstimateMatch
        ? priceEstimateMatch[1].trim()
        : "";

	// DSP Notes section	
	const dspNotesMatch = content.match(
    /DSP Notes:\s*\n([\s\S]*?)\nEst Time Hours:/i
	);

	const dspNotes = dspNotesMatch
    ? dspNotesMatch[1].trim()
    : "";

    // Technician mapping
    const technicianRaw = getField("Technician Name")
        .split("\n")[0]
        .trim();

    const technicianMap = {
        Taylor: "Taylor Hamilton",
        Phil: "Phill Smith",
        Paul: "Paul Darby",
        Nathan: "Nathan Leafe",
		Simon: "Simon",
        Neville: "Neville Terkelson",
        Jimmy: "Jimmy Tran"
    };

    const technicianName =
        technicianMap[technicianRaw] || technicianRaw;

    // Combined Job Description
    const fullJobDescription = [
        "JOB DESCRIPTION",
        getField("Job Description"),
        "",
        "REPAIRS",
        repairs,
        "",
        "PRICE ESTIMATE",
        priceEstimate
    ].join("\n");

    return {
        id: item.json.id || "",
        channelId: item.json.channelId || "",
        authorId: item.json.authorId || "",
        authorName: item.json.authorName || "",
        csrName: item.json.authorName || "",
        timestamp: new Date().toLocaleString("en-GB"),

        customerFirstName: nameParts[0] || "",
        customerLastName: nameParts.slice(1).join(" ") || "",

        customerJobTitle: "",

        emailAddress: getField("Email Address"),

        streetAddress,
        streetAddressDescription: "",

        state,
        suburb,
        postalCode,

        mobileNumber: getField("Mobile Number"),
        phoneNumber: getField("Phone Number"),

        howDidYouHearAboutUs: getField("How did you hear about us?"),

        isDhWsNsEmporium: false,

        jobServices: getField("Job Services"),

        jobStart: parseDateTime(getField("Job Start")),
        jobEnd: parseDateTime(getField("Job End")),

        jobType: getField("Job Type"),

        jobDescription: fullJobDescription,

        dspNotes: dspNotes,

        estTimeHours:
            parseFloat(
                getField("Est Time Hours")
                    .replace(/[^0-9.]/g, "")
            ) || 0,

        estPrice:
            parseFloat(
                getField("Est Price")
                    .replace(/[^0-9.]/g, "")
            ) || 0,

        manJob:
            parseInt(
                getField("Man Job")
                    .replace(/[^0-9]/g, ""),
                10
            ) || 1,

        technicianName,

        recap,

        isCreated: true
    };
}

return input.map(item => ({
    json: parseJob(item)
}));
